-- SIM-PRD-CAL-001 -- Layer 1 starter reference data + agent configs
-- Generated by sql/_gen_047.py. Run AFTER 046_calibration.sql.
-- Optional: the schema works with empty tables and nothing calibrates until a
-- dataset has rows, so you can skip this file entirely and upload your own CSV.
--
-- !! THESE FIGURES ARE AN UNVERIFIED STARTER EXTRACT !!
--
-- They are approximate U.S. national BLS OES annual wage percentiles, entered so
-- the Calibration Layer is exercisable the day it deploys. Both datasets load with
-- needs_review = 1, which caps every field calibrated against them at MODERATE
-- confidence no matter how dense the sample -- nothing here can render as
-- "High confidence" to a user.
--
-- Before promoting either dataset (Admin -> Calibration -> Datasets -> "Mark
-- verified"), download the current OES release from
-- https://www.bls.gov/oes/tables.htm and re-upload it as CSV. The upload upserts
-- on cohort, so a verified extract replaces these rows in place.

-- == Dataset 1: annual wages, straight from OES =============================
INSERT INTO reference_datasets
  (id, layer, name, source, source_url, unit, geography_scope,
   credibility_tier, needs_review, derivation_note, as_of_label,
   last_refreshed, refresh_cadence_days, is_active, created_at)
VALUES ('cALdsOES1', 'L1', 'BLS OES National Wages (starter extract)', 'U.S. Bureau of Labor Statistics -- Occupational Employment and Wage Statistics',
  'https://www.bls.gov/oes/tables.htm', 'usd_year', 'national', 'B', 1,
  'Starter extract, unverified. p10/p50/p90 are national annual wage percentiles by SOC occupation. sample_size holds national employment for the occupation, which is the population the OES establishment survey covers -- a data-density signal, not a respondent count. Major-group (##-0000) rows exist so the cohort ladder has a proxy rung when a specific occupation is not held.',
  'May 2024', '2024-05-01', 365, 1, CURRENT_TIMESTAMP);

-- == Dataset 2: independent consulting rate, derived from dataset 1 =========
-- Credibility C on purpose: a modelled transform of wage data, not a rate
-- survey. Tier C can never render High confidence even once verified.
INSERT INTO reference_datasets
  (id, layer, name, source, source_url, unit, geography_scope,
   credibility_tier, needs_review, derivation_note, as_of_label,
   last_refreshed, refresh_cadence_days, is_active, created_at)
VALUES ('cALdsRAT1', 'L1', 'Independent Consulting Rate (derived from BLS OES)', 'Derived from U.S. Bureau of Labor Statistics OES',
  'https://www.bls.gov/oes/tables.htm', 'usd_hour', 'national', 'C', 1,
  'Modelled proxy, not a rate survey. hourly_rate = annual_wage * 1.35 / (2080 * 0.6) -- an employed-equivalent wage grossed up 35% for self-employment tax, benefits and admin, then divided by billable hours at 60% utilisation. Tiered C deliberately: replace with a licensed rate survey when one is available.',
  'May 2024 (derived)', '2024-05-01', 365, 1, CURRENT_TIMESTAMP);

