-- == Agent configs ==========================================================
-- Only fields that can genuinely be bound to the data above are configured. The
-- remaining L1 agents (linkedin_optimization, booking_page, sow_template,
-- agreement_template, referral_network and the outreach agents) emit no
-- calibratable money figure, so they are deliberately absent rather than
-- configured-but-unbound -- an unbound config asks the agent for nothing and would
-- only read as coverage we do not have. Add them from the admin console as you
-- source datasets for speaking fees, project fees and conversion rates.
INSERT INTO calibration_configs
  (id, agent_key, layer, dataset_id, output_field, field_label, unit,
   method, percentiles_json, sigma_model_pct, min_sample_high,
   min_sample_moderate, band_floor_pct, drift_threshold_pct,
   min_reports_to_reweight, is_enabled, created_at)
VALUES
  ('cALcf0001', 'rate_card', 'L1', 'cALdsRAT1', 'billable_hourly_rate', 'Your billable hourly rate', 'usd_hour',
   'bayes_precision', '[10, 50, 90]', 25, 300, 40, 8.00, 15.00, 30, 1, CURRENT_TIMESTAMP),  -- The root node every other layer references, so it calibrates first (PRD 11, scheduling).
  ('cALcf0002', 'rate_card', 'L1', 'cALdsOES1', 'projected_annual_income', 'Projected annual income at this rate', 'usd_year',
   'bayes_precision', '[10, 50, 90]', 30, 300, 40, 8.00, 15.00, 30, 1, CURRENT_TIMESTAMP),  -- Wider model sigma than the rate itself: an annual projection compounds utilisation assumptions.
  ('cALcf0003', 'consulting_proposal', 'L1', 'cALdsRAT1', 'blended_hourly_rate', 'Blended hourly rate on this proposal', 'usd_hour',
   'bayes_precision', '[10, 50, 90]', 25, 300, 40, 8.00, 15.00, 30, 1, CURRENT_TIMESTAMP),
  ('cALcf0004', 'negotiation_script', 'L1', 'cALdsOES1', 'target_annual_compensation', 'Target annual compensation', 'usd_year',
